('blue-tech', 'Blue-tech', 'Full-stack e-commerce, no separate API server', 'A complete retail platform: product discovery, cart and checkout, coupons, payments and an admin console for orders, shipments, users and reviews. The React front end talks to a single Deno edge function that serves the whole REST API on top of Supabase.', '["Atomic checkout: stock and coupon updates use compare-and-swap so they stay correct under concurrent requests.","Admin console with dashboard stats, analytics, order and shipment management and review moderation.","Email, password and Google sign-in, explicit CORS allow-list and shaped API responses so sensitive columns never reach the client."]', '["React","Vite","Tailwind CSS","Supabase","Deno Edge Functions","PostgreSQL"]', 'https://github.com/Promiles0/Blue-tech', 'https://blue-tech.onrender.com', '/images/projects/blue-tech.jpg', '/videos/blue-tech.mp4', 0, 0, 1, 1, 1, '2026'),
('arovaforex', 'ArovaForex', 'Forecasts, signals and education for traders', 'A trading community platform with public and premium forecasts, real-time likes and comments, a signals area for subscribers, a trading calendar and a full admin dashboard for users, content, analytics and notifications.', '["Role-based user and admin dashboards secured with Supabase row level security.","Real-time engagement on forecasts through Supabase Realtime.","Analytics for user growth, forecast activity and engagement with Recharts."]', '["React","Vite","Tailwind CSS","shadcn/ui","Framer Motion","Supabase","Recharts"]', NULL, 'https://arovaforex.vercel.app', '/images/projects/arovaforex.jpg', NULL, 1, 1, 0, 1, 2, '2025'),
('san-brothers-core', 'San Brothers Core', 'Multi-portal professional services platform', 'One codebase serving three portals for visa and permit processing, certified translation with live interpretation, accounting and business consultancy. Clients book, pay and track services in English, Chinese or Kinyarwanda.', '["React 19 with TanStack Router and Start, deployed on Cloudflare Workers.","Stripe payments and Daily.co video for live interpreter sessions.","Custom i18n, React Hook Form with Zod validation and a Radix-based component library."]', '["React 19","TanStack Router","Cloudflare Workers","Tailwind CSS v4","Supabase","Stripe","Daily.co"]', NULL, 'https://sanbrothers.cn.com', '/images/projects/san-brothers.jpg', NULL, 1, 0, 0, 1, 3, '2026'),
('lifevault', 'LifeVault', 'A private memory vault, organised by moments', 'A personal cloud archive that keeps photos, videos, documents, audio and notes grouped around memories such as a birthday or a trip, rather than folders. Lose a device and everything is still there when you sign in from the next one.', '["Library, timeline, favourites, trash with restore and partial-word search across everything.","Cloudflare R2 for file storage with Supabase Storage as fallback, behind a pluggable provider interface.","Supabase Auth and Postgres with row level security; deploys to Vercel as a single app."]', '["Next.js 16","React 19","TypeScript","Tailwind CSS v4","Supabase","Cloudflare R2"]', NULL, NULL, '/images/projects/lifevault.svg', NULL, 1, 0, 0, 1, 4, '2026'),
('arova', 'Arova', 'Brand site for the Arova trading community', 'The public face of Arova: a fast marketing site with layered hero imagery, section backgrounds and clear calls to action that lead into the ArovaForex platform.', '["Image-led layout with text masks and layered backgrounds.","Built with React, TypeScript and Tailwind on Vite, data on Supabase."]', '["React","TypeScript","Vite","Tailwind CSS","Supabase"]', NULL, 'https://arova.vercel.app', '/images/projects/arova.jpg', NULL, 1, 1, 0, 1, 5, '2025'),
